#include <omp.h>
#include <vector>
#include <string>
#include <cstddef>
#include <algorithm>

struct Book {
    std::string title;
    int pages;
};

/* Return the index of the last Book item in the vector books where Book.pages is less than 100.
   Use OpenMP to search in parallel.
*/
size_t findLastShortBook(std::vector<Book> const& books) {
    if (books.empty()) return books.size(); // sentinel: not found

    // Use a signed type for reduction max; -1 means "not found".
    long long global_last = -1;

#pragma omp parallel
    {
        long long local_last = -1;

#pragma omp for nowait
        for (std::size_t i = 0; i < books.size(); ++i) {
            if (books[i].pages < 100) {
                long long idx = static_cast<long long>(i);
                if (idx > local_last) local_last = idx;
            }
        }

#pragma omp critical
        {
            if (local_last > global_last) global_last = local_last;
        }
    }

    return (global_last < 0) ? books.size() : static_cast<std::size_t>(global_last);
}
